contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take parameters: newBetLimit to set, and wagerAmount to send when calling wager().
    // The test contract must hold at least wagerAmount wei before calling run; the caller of run must fund this contract.
    function run(uint256 newBetLimit, uint256 wagerAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerAmount)); require(wagerAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= wagerAmount);

        // Make the contract open to the public and set the bet limit. InvMutTest is the owner of c.
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(newBetLimit); if (__ESBMC_reverted()) return;

        // Attempt to place a wager by sending wagerAmount. This may revert if wagerAmount != betLimit.
        bool wagerReverted;
        c.wager{value: wagerAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        // Record whether the contract thinks this test contract has a wager
        bool afterWagerHas = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // Now attempt to play. play() may revert (e.g., same block or not a player). We capture revert.
        bool playReverted;
        c.play(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            playReverted = true;
        } else {
            playReverted = false;
        }

        // Observe whether the player is recorded as having wagered after play attempt
        bool afterPlayHas = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // General property to assert:
        // If the wager call succeeded (so afterWagerHas == true) and play executed without reverting,
        // then afterPlayHas must be false (the player's wager state is cleared by play on successful execution).
        assert( !( !wagerReverted && afterWagerHas && !playReverted ) || (afterPlayHas == false) );
    }

    receive() external payable {}
}

