pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newBetLimit, uint256 wagerAmount) internal {
        wagerAmount = bound(wagerAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= wagerAmount);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(newBetLimit) {} catch { return; }
        bool wagerReverted;
        try c.wager{value: wagerAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        bool afterWagerHas;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { afterWagerHas = __r; } catch { return; }
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        bool afterPlayHas;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { afterPlayHas = __r; } catch { return; }
        assertTrue(!( !wagerReverted && afterWagerHas && !playReverted ) || (afterPlayHas == false));
    }

    function testFuzz_run(uint256 newBetLimit, uint256 wagerAmount) public {
        _run(newBetLimit, wagerAmount);
    }

    receive() external payable {}
}
